() => {
  const text = document.body.innerText;
  // Look for release date / availability info
  const keywords = ['release', 'available', 'preorder', 'order', 'launch', 'countries', 'regions', 'June', 'July', 'February', '2024', '2025', 'Coming', 'Available'];
  const lines = text.split('\n');
  return lines.filter(line => keywords.some(k => line.toLowerCase().includes(k.toLowerCase()))).slice(0, 50);
}

() => {
  return {
    url: window.location.href,
    title: document.title,
    bodyLength: document.body.innerText.length,
    sample: document.body.innerText.substring(0, 1000)
  };
}

() => {
  const elements = document.querySelectorAll('p, h1, h2, h3, h4, h5, span, a');
  const results = [];
  for (const el of elements) {
    const text = el.innerText?.trim();
    if (text && (
      text.toLowerCase().includes('available') || 
      text.toLowerCase().includes('release') || 
      text.toLowerCase().includes('preorder') ||
      text.toLowerCase().includes('order') ||
      text.toLowerCase().includes('buy') ||
      text.toLowerCase().includes('february') ||
      text.toLowerCase().includes('countries') ||
      text.toLowerCase().includes('shipping')
    )) {
      results.push(text.substring(0, 200));
    }
  }
  return results.slice(0, 30);
}

() => {
  return {
    h1: document.querySelector('h1')?.innerText,
    h2: Array.from(document.querySelectorAll('h2')).map(e => e.innerText),
    title: document.title,
    url: location.href
  };
}

() => {
  // Find all visible text nodes that contain release/availability info
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, null, false);
  const textNodes = [];
  let node;
  while (node = walker.nextNode()) {
    const t = node.nodeValue.trim();
    if (t && t.length > 5) textNodes.push(t);
  }
  return textNodes.slice(0, 100);
}

() => {
  const els = document.querySelectorAll('p, h1, h2, h3, h4, h5, h6, span, div, a, button, li');
  const results = [];
  for (const el of els) {
    const text = el.innerText?.trim();
    if (text && (
      text.toLowerCase().includes('available') || 
      text.toLowerCase().includes('release') || 
      text.toLowerCase().includes('preorder') ||
      text.toLowerCase().includes('order') ||
      text.toLowerCase().includes('buy') ||
      text.toLowerCase().includes('february') ||
      text.toLowerCase().includes('october') ||
      text.toLowerCase().includes('november') ||
      text.toLowerCase().includes('launch') ||
      text.toLowerCase().includes('shipping') ||
      text.toLowerCase().includes('arrives')
    )) {
      if (text.length < 300) results.push(text);
    }
  }
  return [...new Set(results)].slice(0, 30);
}
